   440  void bam_cigar2rqlens(int n_cigar, const uint32_t *cigar, int *rlen, int *qlen)
   441  {
   442      int k;
   443      *rlen = *qlen = 0;
   444      for (k = 0; k < n_cigar; ++k) {
   445          int type = bam_cigar_type(bam_cigar_op(cigar[k]));
   446          int len = bam_cigar_oplen(cigar[k]);
   447          if (type & 1) *qlen += len;
   448          if (type & 2) *rlen += len;
   449      }
   450  }
   451
   452  int bam_cigar2qlen(int n_cigar, const uint32_t *cigar)
   453  {
   454      int k, l;
   455      for (k = l = 0; k < n_cigar; ++k)
   456          if (bam_cigar_type(bam_cigar_op(cigar[k]))&1)
   457              l += bam_cigar_oplen(cigar[k]);
   458      return l;
   459  }
   460
   461  hts_pos_t bam_cigar2rlen(int n_cigar, const uint32_t *cigar)
   462  {
   463      int k;
   464      hts_pos_t l;
   465      for (k = l = 0; k < n_cigar; ++k)
   466          if (bam_cigar_type(bam_cigar_op(cigar[k]))&2)
   467              l += bam_cigar_oplen(cigar[k]);
   468      return l;
   469  }
