   471  hts_pos_t bam_endpos(const bam1_t *b)
   472  {
   473      if (!(b->core.flag & BAM_FUNMAP) && b->core.n_cigar > 0)
   474          return b->core.pos + bam_cigar2rlen(b->core.n_cigar, bam_get_cigar(b));
   475      else
   476          return b->core.pos + 1;
   477  }
