   479  static int bam_tag2cigar(bam1_t *b, int recal_bin, int give_warning) // return 0 if CIGAR is untouched; 1 if CIGAR is updated with CG
   480  {
   481      bam1_core_t *c = &b->core;
   482      uint32_t cigar_st, n_cigar4, CG_st, CG_en, ori_len = b->l_data, *cigar0, CG_len, fake_bytes;
   483      uint8_t *CG;
   484
   485      // test where there is a real CIGAR in the CG tag to move
   486      if (c->n_cigar == 0 || c->tid < 0 || c->pos < 0) return 0;
   487      cigar0 = bam_get_cigar(b);
   488      if (bam_cigar_op(cigar0[0]) != BAM_CSOFT_CLIP || bam_cigar_oplen(cigar0[0]) != c->l_qseq) return 0;
   489      fake_bytes = c->n_cigar * 4;
   490      if ((CG = bam_aux_get(b, "CG")) == 0) return 0; // no CG tag
   491      if (CG[0] != 'B' || CG[1] != 'I') return 0; // not of type B,I
   492      CG_len = le_to_u32(CG + 2);
   493      if (CG_len < c->n_cigar || CG_len >= 1U<<29) return 0; // don't move if the real CIGAR length is shorter than the fake cigar length
   494
   495      // move from the CG tag to the right position
   496      cigar_st = (uint8_t*)cigar0 - b->data;
   497      c->n_cigar = CG_len;
   498      n_cigar4 = c->n_cigar * 4;
   499      CG_st = CG - b->data - 2;
   500      CG_en = CG_st + 8 + n_cigar4;
   501      if (possibly_expand_bam_data(b, n_cigar4 - fake_bytes) < 0) return -1;
   502      b->l_data = b->l_data - fake_bytes + n_cigar4; // we need c->n_cigar-fake_bytes bytes to swap CIGAR to the right place
   503      memmove(b->data + cigar_st + n_cigar4, b->data + cigar_st + fake_bytes, ori_len - (cigar_st + fake_bytes)); // insert c->n_cigar-fake_bytes empty space to make room
   504      memcpy(b->data + cigar_st, b->data + (n_cigar4 - fake_bytes) + CG_st + 8, n_cigar4); // copy the real CIGAR to the right place; -fake_bytes for the fake CIGAR
   505      if (ori_len > CG_en) // move data after the CG tag
   506          memmove(b->data + CG_st + n_cigar4 - fake_bytes, b->data + CG_en + n_cigar4 - fake_bytes, ori_len - CG_en);
   507      b->l_data -= n_cigar4 + 8; // 8: CGBI (4 bytes) and CGBI length (4)
   508      if (recal_bin)
   509          b->core.bin = hts_reg2bin(b->core.pos, b->core.pos + bam_cigar2rlen(b->core.n_cigar, bam_get_cigar(b)), 14, 5);
   510      if (give_warning)
   511          hts_log_error("%s encodes a CIGAR with %d operators at the CG tag", bam_get_qname(b), c->n_cigar);
   512      return 1;
   513  }
